class Solution {
  public int minOperationsToFlip(String expression) {
    Deque<int[]> values = new ArrayDeque<>(); // {value, cost to flip it}
    Deque<Character> ops = new ArrayDeque<>();
    for (char c : expression.toCharArray()) {
      if (c == '0' || c == '1') {
        values.push(new int[] {c - '0', 1});
        reduce(values, ops);
      } else if (c == ')') {
        ops.pop(); // the matching '('
        reduce(values, ops);
      } else {
        ops.push(c); // '(', '&' or '|'
      }
    }
    return values.peek()[1];
  }

  // apply a pending operator to the two operands on top, if there is one
  private void reduce(Deque<int[]> values, Deque<Character> ops) {
    while (!ops.isEmpty() && ops.peek() != '(' && values.size() >= 2) {
      char op = ops.pop();
      int[] b = values.pop(), a = values.pop();
      values.push(combine(a, b, op));
    }
  }

  private int[] combine(int[] a, int[] b, char op) {
    int cheaper = Math.min(a[1], b[1]);
    if (op == '&') {
      if (a[0] == 1 && b[0] == 1) return new int[] {1, cheaper};
      if (a[0] == 0 && b[0] == 0) return new int[] {0, cheaper + 1};
      return new int[] {0, 1};
    }
    if (a[0] == 0 && b[0] == 0) return new int[] {0, cheaper};
    if (a[0] == 1 && b[0] == 1) return new int[] {1, cheaper + 1};
    return new int[] {1, 1};
  }
}
